// K= 81 | L≤2591 | smem for subject | reg_limit=128
template<typename index_t,typename value_t>
__launch_bounds__(32, 2)
__global__ void shfl_FullDTW_Opt_K81(
    const value_t* __restrict__ Subject,
    value_t* __restrict__ Dist,
    index_t N,index_t L_query,index_t L_subject,index_t padded_stride)
{
    if(blockIdx.x>=N)return;
    const index_t blid=blockIdx.x,thid=threadIdx.x,l=thid;
    const index_t base=blid*padded_stride;
    // Subject loaded on-demand via __ldg (K>64, avoids register spill)
    const value_t* __restrict__ Sbase = Subject + base + 81*l;
    const value_t sv0=(l==0)?(value_t)0:__ldg(Subject+base+81*l-1);
    const value_t sv1=__ldg(Sbase+0);
    const value_t sv2=__ldg(Sbase+1);
    const value_t sv3=__ldg(Sbase+2);
